const headline = $input.first().json;
const facts = headline.key_facts || [];
const factsText = facts.slice(0, 3).map(f => `- ${f.fact || f} (confidence: ${f.confidence || 'unknown'})`).join('\n');

const prompt = `Write a punchy 30-60 second script for a news short video. Must include: hook (first 3 seconds), key facts, call-to-action.

Headline: ${headline.original_title}
Research Summary: ${headline.summary || ''}
Key Facts:
${factsText}

Use these markers:
[PAUSE] - natural pause (0.5-1 second)
[EMPHASIS:word] - emphasize this word
[SOUND:alert] - sound effect cue

Start with a hook that grabs attention. Keep language conversational and energetic. End with a clear CTA to subscribe/follow.

Script:`;

return { json: { headline_id: headline.id, prompt: prompt, headline_title: headline.original_title } };

const response = $input.first().json;
const scriptText = response.content?.[0]?.text || response.content || '';

// Clean markers for word count
let clean = scriptText.replace(/\[PAUSE\]/g, ' ');
clean = clean.replace(/\[EMPHASIS:[^\]]+\]/g, '$1');
clean = clean.replace(/\[EMPHASIS\]/g, '');
clean = clean.replace(/\[SOUND:[^\]]+\]/g, '');
clean = clean.replace(/\s+/g, ' ').trim();

const words = clean.split(/\s+/).filter(w => w.length > 0);
const wordCount = words.length;
const durationSeconds = Math.round((wordCount / 150) * 60);

const errors = [];
if (wordCount < 45) errors.push(`Too short: ${wordCount} words (min 45)`);
if (wordCount > 150) errors.push(`Too long: ${wordCount} words (max 150)`);
if (durationSeconds < 20) errors.push(`Too short: ${durationSeconds}s`);
if (durationSeconds > 90) errors.push(`Too long: ${durationSeconds}s`);
if (!scriptText.includes('[PAUSE]')) errors.push('Missing [PAUSE] markers');

const hasHook = /breaking|just announced|here's what|you need to know|big news/i.test(scriptText);
if (!hasHook) errors.push('Weak hook');

const hasCTA = /subscribe|follow|like|share/i.test(scriptText);
if (!hasCTA) errors.push('Missing CTA');

return {
  json: {
    headline_id: $input.first().json.headline_id,
    headline_title: $input.first().json.headline_title,
    script_content: scriptText,
    word_count: wordCount,
    duration_seconds: durationSeconds,
    valid: errors.length === 0,
    errors: errors,
    script_type: 'daily_short',
    tone: 'professional'
  }
};

const headlines = $input.first().json;
const headlinesText = headlines.map((h, i) => `${i+1}. ${h.original_title} - ${(h.summary || '').substring(0, 100)}...`).join('\n');

const prompt = `Rank these world news stories by importance, impact, and geopolitical relevance. Return the top 5 most significant stories.

Headlines:
${headlinesText}

Respond in JSON:
{
  "top_stories": [
    {
      "title": "Story title",
      "ranking_reason": "Why this story matters"
    }
  ]
}`;

return { json: { headlines: headlines, prompt: prompt } };

const response = $input.first().json;
let text = response.content?.[0]?.text || '';

if (text.includes('```json')) text = text.split('```json')[1].split('```')[0].trim();
else if (text.includes('```')) {
  const parts = text.split('```');
  if (parts.length >= 3) text = parts[1].trim();
}

let ranking;
try { ranking = JSON.parse(text); } catch {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) { try { ranking = JSON.parse(match[0]); } catch {} }
}

const topStories = ranking?.top_stories || [];
const storiesText = topStories.map((s, i) => `Story ${i+1}: ${s.title}\nReason: ${s.ranking_reason}`).join('\n\n');

const prompt = `Write a professional 5-10 minute news recap script for YouTube.
Format: Intro (10s) -> 5 story segments (2 min each) -> Outro (30s)

Include:
- Host intro: "Welcome to this week's news brief..."
- For each story: headline, key facts, why it matters, brief analysis
- Smooth transitions between stories
- Outro with call-to-action to subscribe

Use [PAUSE] and [EMPHASIS:word] markers.
Maintain consistent host tone: professional, engaging, conversational.

Target: 750-1500 words (~5-10 minutes at 150 wpm)

Top Stories:
${storiesText}

Full Script:`;

return { json: { prompt: prompt, top_stories: topStories } };

const response = $input.first().json;
const scriptText = response.content?.[0]?.text || '';

let clean = scriptText.replace(/\[PAUSE\]/g, ' ');
clean = clean.replace(/\[EMPHASIS:[^\]]+\]/g, '$1');
clean = clean.replace(/\[EMPHASIS\]/g, '');
clean = clean.replace(/\[SOUND:[^\]]+\]/g, '');
clean = clean.replace(/\s+/g, ' ').trim();

const words = clean.split(/\s+/).filter(w => w.length > 0);
const wordCount = words.length;
const durationSeconds = Math.round((wordCount / 150) * 60);

const errors = [];
if (wordCount < 750) errors.push(`Too short: ${wordCount} words (min 750)`);
if (wordCount > 1500) errors.push(`Too long: ${wordCount} words (max 1500)`);
if (durationSeconds < 300) errors.push(`Too short: ${durationSeconds}s`);
if (durationSeconds > 600) errors.push(`Too long: ${durationSeconds}s`);

const hasIntro = /intro|welcome/i.test(scriptText);
if (!hasIntro) errors.push('Missing intro');

const hasOutro = /outro|thanks for watching/i.test(scriptText);
if (!hasOutro) errors.push('Missing outro');

const segmentMarkers = ['story', 'segment', 'next up', 'moving on'];
const segmentCount = segmentMarkers.reduce((count, m) => count + (scriptText.toLowerCase().includes(m) ? 1 : 0), 0);
if (segmentCount < 3) errors.push(`Too few segments: ${segmentCount}`);

return {
  json: {
    script_content: scriptText,
    word_count: wordCount,
    duration_seconds: durationSeconds,
    valid: errors.length === 0,
    errors: errors,
    script_type: 'weekly',
    tone: 'professional',
    headline_id: null
  }
};
